import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface InlinePillTakeoverProps {
  before: string;
  insert: string;
  after: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  pillWidth?: number;
  pillColor?: string;
  pillTextColor?: string;
  expandFrames?: number;
  pillRevealHeightScale?: number;
  pillGrowAt?: number;
  pillGrowFrames?: number;
  pillGrowWidthScale?: number;
  pillGrowHeightScale?: number;
  outerExitFrames?: number;
  takeoverAt?: number;
  takeoverScale?: number;
  blur?: number;
  speed?: number;
  className?: string;
}

const PRE_CUT_FRAMES = 12;
const TAKEOVER_SETTLE_FRAMES = 6;
const PRE_CUT_CAMERA_SCALE = 1.25;
const CAMERA_CUT_ENTRY_PROGRESS = 0.86;
const expandEasing = Easing.out(Easing.quad);
const pillGrowEasing = Easing.inOut(Easing.quad);
const fadeEasing = Easing.in(Easing.cubic);
const preCutEasing = Easing.out(Easing.quad);
const takeoverSettleEasing = Easing.out(Easing.cubic);

function InlinePillTakeoverBase({
  before,
  insert,
  after,
  fontSize = 52,
  color = "#fff3df",
  fontWeight = 400,
  pillWidth = 260,
  pillColor = "#fffaf0",
  pillTextColor = "#1c1210",
  expandFrames = 12,
  pillRevealHeightScale = 0.35,
  pillGrowAt = 12,
  pillGrowFrames = 24,
  pillGrowWidthScale = 1.08,
  pillGrowHeightScale = 1.16,
  outerExitFrames = 18,
  takeoverAt = 12,
  takeoverScale = 2.15,
  blur = 12,
  speed = 1,
  className,
}: InlinePillTakeoverProps) {
  const frame = useCurrentFrame() * speed;
  const safeExpandFrames = Math.max(expandFrames, 0.001);
  const pillGrowEnd = pillGrowAt + Math.max(pillGrowFrames, 0.001);
  const outerExitEnd = Math.max(outerExitFrames, 2.001);
  const dashWidth = fontSize * 0.72;
  const pillHeight = fontSize * 1.22;
  const cutAt = takeoverAt + PRE_CUT_FRAMES;
  const cutEntryScale = takeoverScale * CAMERA_CUT_ENTRY_PROGRESS;

  const expand = interpolate(frame, [0, safeExpandFrames], [0, 1], {
    easing: expandEasing,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pillGrowProgress = interpolate(
    frame,
    [pillGrowAt, pillGrowEnd],
    [0, 1],
    {
      easing: pillGrowEasing,
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const outerExit = interpolate(frame, [2, outerExitEnd], [0, 1], {
    easing: fadeEasing,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pillTextOpacity = frame >= 3 ? 1 : 0;
  const preCutCameraScale = interpolate(
    frame,
    [takeoverAt, cutAt - 1],
    [1, PRE_CUT_CAMERA_SCALE],
    {
      easing: preCutEasing,
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const postCutCameraScale = interpolate(
    frame,
    [cutAt, cutAt + TAKEOVER_SETTLE_FRAMES],
    [cutEntryScale, takeoverScale],
    {
      easing: takeoverSettleEasing,
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const cameraScale = frame < cutAt ? preCutCameraScale : postCutCameraScale;
  const revealedPillWidth = dashWidth + (pillWidth - dashWidth) * expand;
  const revealedPillHeight =
    pillHeight * (pillRevealHeightScale + (1 - pillRevealHeightScale) * expand);
  const pillWidthGrow = 1 + (pillGrowWidthScale - 1) * pillGrowProgress;
  const pillHeightGrow = 1 + (pillGrowHeightScale - 1) * pillGrowProgress;
  const animatedPillWidth = revealedPillWidth * pillWidthGrow;
  const animatedPillHeight = revealedPillHeight * pillHeightGrow;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        background: "transparent",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${cameraScale})`,
          transformOrigin: "center",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            width: "100%",
            gap: `${fontSize * 0.16}px`,
            whiteSpace: "nowrap",
            fontFamily:
              "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
            fontSize,
            fontWeight,
            letterSpacing: "-0.02em",
            lineHeight: 1,
          }}
        >
          <span
            style={{
              flex: 1,
              textAlign: "right",
              color,
              opacity: 1 - outerExit,
              filter: outerExit > 0 ? `blur(${blur * outerExit}px)` : undefined,
            }}
          >
            {before}
          </span>

          <span
            style={{
              position: "relative",
              display: "inline-block",
              flexShrink: 0,
              width: animatedPillWidth,
              height: animatedPillHeight,
              overflow: "hidden",
              borderRadius: animatedPillHeight / 2,
              background: pillColor,
              color: pillTextColor,
            }}
          >
            <span
              style={{
                position: "absolute",
                top: "50%",
                left: "50%",
                translate: "-50% -50%",
                fontSize: fontSize * 0.84,
                opacity: pillTextOpacity,
                whiteSpace: "nowrap",
              }}
            >
              {insert}
            </span>
          </span>

          <span
            style={{
              flex: 1,
              textAlign: "left",
              color,
              opacity: 1 - outerExit,
              filter: outerExit > 0 ? `blur(${blur * outerExit}px)` : undefined,
            }}
          >
            {after}
          </span>
        </div>
      </div>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  before: {
    type: "text-content",
    default: "powering 20%",
    description: "Text before pill",
  },
  insert: {
    type: "text-content",
    default: "Start building",
    description: "Pill text",
  },
  after: {
    type: "text-content",
    default: "of the Internet.",
    description: "Text after pill",
  },
  fontSize: {
    type: "number",
    min: 24,
    max: 120,
    step: 1,
    default: 52,
    description: "Font size",
    hiddenFromList: false,
  },
  pillWidth: {
    type: "number",
    min: 100,
    max: 600,
    step: 5,
    default: 260,
    description: "Expanded pill width",
    hiddenFromList: false,
  },
  expandFrames: {
    type: "number",
    min: 6,
    max: 45,
    step: 1,
    default: 12,
    description: "Width reveal frames",
    hiddenFromList: false,
  },
  pillRevealHeightScale: {
    type: "number",
    min: 0.05,
    max: 1,
    step: 0.05,
    default: 0.35,
    description: "Initial reveal height scale",
    hiddenFromList: false,
  },
  pillGrowAt: {
    type: "number",
    min: 6,
    max: 30,
    step: 1,
    default: 12,
    description: "Pill growth start frame",
    hiddenFromList: false,
  },
  pillGrowFrames: {
    type: "number",
    min: 6,
    max: 36,
    step: 1,
    default: 24,
    description: "Pill growth frames",
    hiddenFromList: false,
  },
  pillGrowWidthScale: {
    type: "number",
    min: 1,
    max: 1.3,
    step: 0.01,
    default: 1.08,
    description: "Final pill width scale",
    hiddenFromList: false,
  },
  pillGrowHeightScale: {
    type: "number",
    min: 1,
    max: 1.5,
    step: 0.01,
    default: 1.16,
    description: "Final pill height scale",
    hiddenFromList: false,
  },
  outerExitFrames: {
    type: "number",
    min: 6,
    max: 30,
    step: 1,
    default: 18,
    description: "Outer text exit frames",
    hiddenFromList: false,
  },
  takeoverAt: {
    type: "number",
    min: 12,
    max: 40,
    step: 1,
    default: 12,
    description: "Camera move start frame",
    hiddenFromList: false,
  },
  takeoverScale: {
    type: "number",
    min: 1,
    max: 4,
    step: 0.05,
    default: 2.15,
    description: "Final takeover scale",
    hiddenFromList: false,
  },
  blur: {
    type: "number",
    min: 0,
    max: 30,
    step: 1,
    default: 12,
    description: "Outer text blur",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#fff3df",
    description: "Outer text color",
  },
  pillColor: {
    type: "color",
    default: "#fffaf0",
    description: "Pill color",
  },
  pillTextColor: {
    type: "color",
    default: "#1c1210",
    description: "Pill text color",
  },
  fontWeight: {
    type: "enum",
    default: "400",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["before","insert","after","fontSize","pillWidth","expandFrames","pillRevealHeightScale","pillGrowAt","pillGrowFrames","pillGrowWidthScale","pillGrowHeightScale","outerExitFrames","takeoverAt","takeoverScale","blur","color","pillColor","pillTextColor","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  before: "powering 20%",
  insert: "Start building",
  after: "of the Internet.",
  fontSize: 52,
  pillWidth: 260,
  expandFrames: 12,
  pillRevealHeightScale: 0.35,
  pillGrowAt: 12,
  pillGrowFrames: 24,
  pillGrowWidthScale: 1.08,
  pillGrowHeightScale: 1.16,
  outerExitFrames: 18,
  takeoverAt: 12,
  takeoverScale: 2.15,
  blur: 12,
  color: "#fff3df",
  pillColor: "#fffaf0",
  pillTextColor: "#1c1210",
  fontWeight: "400",
  speed: 1,
};

type InlinePillTakeoverElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof InlinePillTakeoverBase>;

const InlinePillTakeoverInner = forwardRef<
  HTMLDivElement,
  InlinePillTakeoverElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<InlinePillTakeover>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <InlinePillTakeoverBase
          {...(componentProps as unknown as ComponentProps<typeof InlinePillTakeoverBase>)}
        />
      </div>
    </Sequence>
  );
});

export const InlinePillTakeover = Interactive.withSchema({
  Component: InlinePillTakeoverInner,
  componentName: "<InlinePillTakeover>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
